export const zPollContactEnrichmentResultData = z.object({
    body: z.object({
        apiKey: z.string(),
        taskId: z.string()
    }),
    path: z.optional(z.never()),
    query: z.optional(z.never())
});

/**
 * Default Response
 */
export const zPollContactEnrichmentResultResponse = z.object({
    output: z.object({
        profile: z.object({
            emails: z.array(z.object({
                email: z.string(),
                type: z.enum([
                    'work',
                    'personal',
                    'other',
                    'unknown',
                    'generic'
                ]),
                status: z.optional(z.enum([
                    'valid',
                    'risky',
                    'unknown',
                    'invalid'
                ]))
            })),
            phoneNumbers: z.array(z.object({
                number: z.string(),
                type: z.enum([
                    'mobile',
                    'other',
                    'unknown'
                ])
            })),
            status: z.enum([
                'started',
                'live-enriching',
                'grabbing-contact-info',
                'completed',
                'failed'
            ]),
            error: z.optional(z.string())
        }),
        done: z.boolean()
    }),
    chargeInfo: z.union([
        z.object({
            method: z.enum(['charged-now']),
            creditsCharged: z.number()
        }),
        z.object({
            method: z.enum(['charging-later']),
            message: z.string()
        }),
        z.object({
            method: z.enum(['charged-for-async-process']),
            creditsCharged: z.number(),
            message: z.string()
        }),
        z.object({
            method: z.enum(['free']),
            message: z.string()
        })
    ]),
    warnings: z.optional(z.union([
        z.array(z.object({
            field: z.string(),
            message: z.string()
        })),
        z.null()
    ]))
});

export const zPollBatchContactEnrichmentData = z.object({
    body: z.object({
        apiKey: z.string(),
        taskId: z.string().min(1),
        cursor: z.optional(z.union([
            z.string(),
            z.null()
        ])),
        take: z.optional(z.int().gt(0).lte(100)).default(100)
    }),
    path: z.optional(z.never()),
    query: z.optional(z.never())
});

/**
 * Default Response
 */
export const zPollBatchContactEnrichmentResponse = z.object({
    output: z.object({
        overallStats: z.object({
            totalPeopleToFetch: z.int().gte(0),
            numCompleted: z.int().gte(0),
            numRemaining: z.int().gte(0),
            numRejected: z.int().gte(0),
            numDuplicates: z.int().gte(0)
        }),
        done: z.boolean(),
        pageResults: z.array(z.object({
            inputs: z.object({
                linkedinUrl: z.object({
                    value: z.url().regex(/^(https?:\/\/)?(\w+\.)?linkedin\.\w+(\.\w+)?\/in\/(?<slug>[^\/\?#]+)\/?(\?.*)?(#.*)?$/)
                })
            }),
            outputs: z.optional(z.union([
                z.object({
                    emails: z.array(z.object({
                        email: z.string(),
                        type: z.enum([
                            'work',
                            'personal',
                            'other',
                            'unknown',
                            'generic'
                        ]),
                        status: z.optional(z.enum([
                            'valid',
                            'risky',
                            'unknown',
                            'invalid'
                        ]))
                    })),
                    phoneNumbers: z.array(z.object({
                        number: z.string(),
                        type: z.enum([
                            'mobile',
                            'other',
                            'unknown'
                        ])
                    }))
                }),
                z.null()
            ]))
        })),
        nextCursor: z.optional(z.union([
            z.string(),
            z.null()
        ]))
    }),
    chargeInfo: z.union([
        z.object({
            method: z.enum(['charged-now']),
            creditsCharged: z.number()
        }),
        z.object({
            method: z.enum(['charging-later']),
            message: z.string()
        }),
        z.object({
            method: z.enum(['charged-for-async-process']),
            creditsCharged: z.number(),
            message: z.string()
        }),
        z.object({
            method: z.enum(['free']),
            message: z.string()
        })
    ]),
    warnings: z.optional(z.union([
        z.array(z.object({
            field: z.string(),
            message: z.string()
        })),
        z.null()
    ]))
});

