export const zCompanyCountResponse = z.object({
    output: z.object({
        count: z.number()
    }),
    chargeInfo: z.union([
        z.object({
            method: z.enum(['charged-now']),
            creditsCharged: z.number()
        }),
        z.object({
            method: z.enum(['charging-later']),
            message: z.string()
        }),
        z.object({
            method: z.enum(['charged-for-async-process']),
            creditsCharged: z.number(),
            message: z.string()
        }),
        z.object({
            method: z.enum(['free']),
            message: z.string()
        })
    ]),
    warnings: z.optional(z.union([
        z.array(z.object({
            field: z.string(),
            message: z.string()
        })),
        z.null()
    ]))
});

