export const zGoogleMapsSearchData = z.object({
    body: z.object({
        apiKey: z.string(),
        name: z.optional(z.union([
            z.string(),
            z.null()
        ])),
        query: z.string().min(1),
        maxResults: z.optional(z.int().gt(0).lte(10000)).default(100),
        strategy: z.union([
            z.object({
                strategy: z.enum(['whole-usa'])
            }),
            z.object({
                strategy: z.enum(['specific-areas']),
                unionAll: z.array(z.union([z.object({
                        regionType: z.enum(['circle']),
                        center: z.object({
                            latitude: z.number().gte(-90).lte(90),
                            longitude: z.number().gte(-180).lte(180)
                        }),
                        radiusMiles: z.optional(z.number().gt(0).lte(250)).default(25)
                    }), z.object({
                        regionType: z.enum(['rectangle']),
                        northwestCorner: z.object({
                            latitude: z.number().gte(-90).lte(90),
                            longitude: z.number().gte(-180).lte(180)
                        }),
                        southeastCorner: z.object({
                            latitude: z.number().gte(-90).lte(90),
                            longitude: z.number().gte(-180).lte(180)
                        })
                    })]))
            })
        ])
    }),
    path: z.optional(z.never()),
    query: z.optional(z.never())
});

/**
 * Default Response
 */
export const zGoogleMapsSearchResponse = z.object({
    output: z.object({
        searchID: z.string()
    }),
    chargeInfo: z.union([
        z.object({
            method: z.enum(['charged-now']),
            creditsCharged: z.number()
        }),
        z.object({
            method: z.enum(['charging-later']),
            message: z.string()
        }),
        z.object({
            method: z.enum(['charged-for-async-process']),
            creditsCharged: z.number(),
            message: z.string()
        }),
        z.object({
            method: z.enum(['free']),
            message: z.string()
        })
    ]),
    warnings: z.optional(z.union([
        z.array(z.object({
            field: z.string(),
            message: z.string()
        })),
        z.null()
    ]))
});

