export const zTextToCompanySearchData = z.object({
    body: z.object({
        apiKey: z.string(),
        query: z.string().min(1),
        pageSize: z.optional(z.int().gt(0).lte(1000)).default(25),
        cursor: z.optional(z.union([
            z.string(),
            z.null()
        ]))
    }),
    path: z.optional(z.never()),
    query: z.optional(z.never())
});

