export const zTextToProfileSearchData = z.object({
    body: z.object({
        apiKey: z.string(),
        query: z.string().min(1),
        pageSize: z.optional(z.int().gt(0).lte(1000)).default(25),
        getDetailedEducation: z.optional(z.union([
            z.boolean().default(false),
            z.null()
        ])).default(false),
        getDetailedWorkExperience: z.optional(z.union([
            z.boolean().default(false),
            z.null()
        ])).default(false),
        cursor: z.optional(z.union([
            z.string(),
            z.null()
        ]))
    }),
    path: z.optional(z.never()),
    query: z.optional(z.never())
});

