export const zTextToCombinedSearchData = z.object({
    body: z.object({
        apiKey: z.string(),
        query: z.string().min(1),
        companyItemLimit: z.optional(z.union([
            z.number().lte(1000),
            z.null()
        ])),
        profileItemLimit: z.number().lte(1000),
        companyExclusionListIDs: z.optional(z.union([
            z.array(z.string()),
            z.null()
        ])),
        prospectExclusionListIDs: z.optional(z.union([
            z.array(z.string()),
            z.null()
        ])),
        getDetailedEducation: z.optional(z.union([
            z.boolean().default(false),
            z.null()
        ])).default(false),
        getDetailedWorkExperience: z.optional(z.union([
            z.boolean().default(false),
            z.null()
        ])).default(false)
    }),
    path: z.optional(z.never()),
    query: z.optional(z.never())
});

